  .ew-sheet { min-width: 0; max-width: 100%; background: var(--ew-color-bg-surface); color: inherit; border: 1px solid var(--ew-color-border-subtle); }
  .ew-sheet__head { display: flex; align-items: center; justify-content: space-between; gap: 8px; min-width: 0; padding: var(--ew-card-pad, 12px); border-bottom: 1px solid var(--ew-color-border-subtle); }
