  .ew-sheet[data-size="sm"] { --ew-spec-size: sm; }
  .ew-sheet[data-size="md"] { --ew-spec-size: md; }
  .ew-sheet:not([data-size]) { --ew-spec-size: md; }
  @media (prefers-reduced-motion: reduce) {
    .ew-sheet, .ew-sheet *, .ew-sheet *::before, .ew-sheet *::after {
      transition: none !important;
      animation: none !important;
    }
  }
